1	import { describe, expect, it } from 'vitest';
2	import fs from 'node:fs';
3	import path from 'node:path';
4	import { fileURLToPath } from 'node:url';
5	import { validateSpec } from './validate.js';
6	
7	const here = path.dirname(fileURLToPath(import.meta.url));
8	
9	function fullSpec(overrides: Partial<Record<string, string>> = {}): string {
10	  const sections: Record<string, string> = {
11	    tier: `### 5.1 Risk tier
12	
13	- **Tier**: limited
14	- **Justification**: Chatbot answering policy questions; no automated decisions about people.
15	- **Sign-off**: not required (tier below high)`,
16	    data: `### 5.2 Data provenance & privacy
17	
18	- **Data sources**: internal policy docs; user questions at runtime
19	- **PII involved?**: no
20	- **Retention**: prompts kept 30 days, then hard-deleted
21	- **Used for training?**: no; provider training disabled`,
22	    oversight: `### 5.3 Human oversight
23	
24	- **Automation level**: assistive
25	- **Override path**: support team can correct answers via admin panel
26	- **Kill switch**: feature flag chat_enabled, ops on-call, off within 5 minutes`,
27	    evaluation: `### 5.4 Evaluation plan
28	
29	- **Pre-ship metrics & thresholds**: groundedness >= 0.85; refusal rate <= 2%
30	- **Eval dataset**: eval/policy-qa.jsonl, 300 questions from real support tickets
31	- **Who runs it and when**: CI on every prompt change`,
32	    bias: `### 5.5 Bias & fairness
33	
34	- **Groups at risk of disparate impact**: non-native English speakers
35	- **Mitigations**: multilingual eval slice; simplified-language prompt rule
36	- **How tested**: disaggregated groundedness by question language`,
37	    monitoring: `### 5.6 Monitoring & rollback
38	
39	- **Production monitoring**: thumbs-down rate, refusal rate, latency
40	- **Degradation definition**: thumbs-down > 10% over 24h
41	- **Rollback trigger & procedure**: on-call flips chat_enabled off; users see the legacy FAQ`,
42	    transparency: `### 5.7 Transparency & incident response
43	
44	- **User disclosure**: "AI assistant" label in the chat header
45	- **Incident owner**: Dana Rivers (support-eng rotation)
46	- **Incident path**: in-chat report -> triage queue -> fix or disable, response within 24h`
47	  };
48	  Object.assign(sections, overrides);
49	  return `# Spec: Policy Chatbot
50	
51	## 1. Objective
52	
53	Answer policy questions.
54	
55	## 5. Responsible AI Gate
56	
57	${Object.values(sections).join('\n\n')}
58	
59	## 6. Rollout
60	
61	Later.`;
62	}
63	
64	describe('validateSpec', () => {
65	  it('blocks a spec with no gate section', () => {
66	    const result = validateSpec('# Spec\n\n## Objective\n\nBuild a thing.');
67	    expect(result.verdict).toBe('BLOCK');
68	    expect(result.findings[0].checkId).toBe('structure');
69	  });
70	
71	  it('passes a fully answered gate', () => {
72	    const result = validateSpec(fullSpec());
73	    expect(result.findings).toEqual([]);
74	    expect(result.verdict).toBe('PASS');
75	    expect(result.tier).toBe('limited');
76	  });
77	
78	  it('blocks the untouched template (empty fields)', () => {
79	    const template = fs.readFileSync(
80	      path.join(here, '../../assets/rai-spec-template.md'),
81	      'utf8'
82	    );
83	    const result = validateSpec(template);
84	    expect(result.verdict).toBe('BLOCK');
85	    expect(result.findings.some((f) => f.message.includes('Unanswered field'))).toBe(true);
86	  });
87	
88	  it('blocks placeholder answers', () => {
89	    const result = validateSpec(
90	      fullSpec({
91	        data: `### 5.2 Data provenance & privacy
92	
93	- **Data sources**: TBD
94	- **PII involved?**: no
95	- **Retention**: 30 days
96	- **Used for training?**: no`
97	      })
98	    );
99	    expect(result.verdict).toBe('BLOCK');
100	    expect(result.findings.some((f) => f.checkId === 'data-privacy')).toBe(true);
101	  });
102	
103	  it('blocks a missing subsection', () => {
104	    const spec = fullSpec();
105	    const withoutBias = spec.replace(/### 5\.5 Bias & fairness[\s\S]*?(?=### 5\.6)/, '');
106	    const result = validateSpec(withoutBias);
107	    expect(result.verdict).toBe('BLOCK');
108	    expect(result.findings.some((f) => f.checkId === 'bias' && f.message.includes('Missing'))).toBe(
109	      true
110	    );
111	  });
112	
113	  it('blocks high risk without sign-off', () => {
114	    const result = validateSpec(
115	      fullSpec({
116	        tier: `### 5.1 Risk tier
117	
118	- **Tier**: high
119	- **Justification**: Screens job applications automatically.
120	- **Sign-off**: not required (tier below high)`
121	      })
122	    );
123	    expect(result.verdict).toBe('BLOCK');
124	    expect(result.findings.some((f) => f.message.includes('sign-off'))).toBe(true);
125	  });
126	
127	  it('accepts high risk with a named sign-off', () => {
128	    const result = validateSpec(
129	      fullSpec({
130	        tier: `### 5.1 Risk tier
131	
132	- **Tier**: high
133	- **Justification**: Screens job applications automatically.
134	- **Sign-off**: Ana Pop (Head of Compliance), 2026-08-01`
135	      })
136	    );
137	    expect(result.findings.filter((f) => f.checkId === 'risk-tier')).toEqual([]);
138	  });
139	
140	  it('blocks a prohibited tier', () => {
141	    const result = validateSpec(
142	      fullSpec({
143	        tier: `### 5.1 Risk tier
144	
145	- **Tier**: prohibited
146	- **Justification**: Social scoring.
147	- **Sign-off**: n/a`
148	      })
149	    );
150	    expect(result.verdict).toBe('BLOCK');
151	    expect(result.findings.some((f) => f.message.includes('must not be built'))).toBe(true);
152	  });
153	
154	  it('blocks an unrecognized tier value', () => {
155	    const result = validateSpec(
156	      fullSpec({
157	        tier: `### 5.1 Risk tier
158	
159	- **Tier**: medium-ish
160	- **Justification**: Feels fine.
161	- **Sign-off**: not required (tier below high)`
162	      })
163	    );
164	    expect(result.verdict).toBe('BLOCK');
165	    expect(result.tier).toBeNull();
166	  });
167	
168	  it('accepts the branded "## FRAI Gate" heading', () => {
169	    const spec = fullSpec().replace('## 5. Responsible AI Gate', '## FRAI Gate');
170	    const result = validateSpec(spec);
171	    expect(result.verdict).toBe('PASS');
172	    expect(result.tier).toBe('limited');
173	  });
174	
175	  it('warns when the evaluation plan has no numbers', () => {
176	    const result = validateSpec(
177	      fullSpec({
178	        evaluation: `### 5.4 Evaluation plan
179	
180	- **Pre-ship metrics & thresholds**: we will check answers look good
181	- **Eval dataset**: some real questions
182	- **Who runs it and when**: the team, before release`
183	      })
184	    );
185	    expect(result.verdict).toBe('WARN');
186	    expect(
187	      result.findings.some((f) => f.checkId === 'evaluation' && f.severity === 'warn')
188	    ).toBe(true);
189	  });
190	});
