582	    !options.scan &&
583	    !options.ci &&
584	    !options.setup &&
585	    !options.listDocs &&
586	    !options.clean &&
587	    !options.update &&
588	    !options.exportPdf &&
589	    !options.key;
590	  if (showConfigOnly) {
591	    showConfigStatus();
592	    return;
