99	export function calculateRiskLevel(answers) {
100	  const { core, impact, data, monitoring, bias } = answers;
101	  let score = 0;
102	  const factors = [];
103	
104	  if (core.dataType === 'sensitive') {
105	    score += 3;
106	    factors.push('Sensitive data');
107	  } else if (core.dataType.includes('personal')) {
108	    score += 2;
109	    factors.push('Personal data');
110	  }
111	
112	  const impactValue = impact ? Object.values(impact)[0] : null;
113	  if (impactValue === 'critical') {
114	    score += 4;
115	    factors.push('Critical impact');
116	  } else if (impactValue === 'high') {
117	    score += 3;
118	    factors.push('High impact');
119	  } else if (impactValue === 'medium') {
120	    score += 2;
121	    factors.push('Medium impact');
122	  }
123	
124	  if (monitoring.monitoring === 'no-monitoring') {
125	    score += 2;
126	    factors.push('No monitoring');
127	  } else if (monitoring.monitoring === 'basic-logging') {
128	    score += 1;
129	    factors.push('Basic monitoring');
130	  }
131	
132	  if (bias.biasConsiderations === 'not-applicable') {
133	    score += 2;
134	    factors.push('No bias considerations');
135	  } else if (bias.biasConsiderations === 'planning') {
136	    score += 1;
137	    factors.push('Bias planning needed');
138	  }
139	
140	  if (core.purpose === 'user-facing') {
141	    score += 1;
142	    factors.push('User-facing');
143	  }
144	
145	  let level;
146	  if (score >= 7) {
147	    level = 'Critical';
148	  } else if (score >= 5) {
149	    level = 'High';
150	  } else if (score >= 3) {
151	    level = 'Medium';
152	  } else {
153	    level = 'Low';
154	  }
155	
156	  return { level, score, factors };
157	}
