**Location:** `/private/tmp/100-tricks-runs/d14/without/h2-eval-thresholds/r3/packages/frai-core/src/eval/index.js`

The `runEvaluations` function accepts custom metrics in two forms:

```javascript
export function runEvaluations({
  outputs,
  references,
  metrics = DEFAULT_METRICS  // optional custom metrics array
} = {})
```

### Custom Metric Support

Each metric in the array can be either:

1. **A function** - Called directly with `(outputs, references)`:
   ```javascript
   function myMetric(outputs, references) {
     return { id: 'my_metric', score: 0.95, ... };
   }
   ```

2. **An object with an `evaluate` method** - Called as `metric.evaluate(outputs, references)`:
   ```javascript
   {
     evaluate(outputs, references) {
       return { id: 'my_metric', score: 0.95, ... };
     }
   }
   ```

The handler validates that metrics are either functions or objects with `evaluate` methods:
```javascript
metrics.map((metric) => {
  if (typeof metric === 'function') {
    return metric(outs, refs);
  }
  if (metric && typeof metric.evaluate === 'function') {
    return metric.evaluate(outs, refs);
  }
  throw new Error('Invalid metric supplied to runEvaluations.');
});
```

## Example Metric Implementation

From the exact_match metric:
```javascript
export function exactMatchMetric(outputs, references) {
  const outs = toArray(outputs);
  const refs = toArray(references);

  if (!outs.length || !refs.length || outs.length !== refs.length) {
    return {
      id: 'exact_match',
      label: 'Exact Match',
      score: null,
      total: outs.length,
      matches: 0,
      details: 'Outputs and references must be non-empty arrays of equal length...'
    };
  }

  let matches = 0;
  const perSample = [];
  outs.forEach((output, index) => {
    const predicted = asString(output).trim().toLowerCase();
    const expected = asString(refs[index]).trim().toLowerCase();
    const match = predicted === expected;
    if (match) matches += 1;
    perSample.push({ index, match, predicted, expected });
  });

  return {
    id: 'exact_match',
    label: 'Exact Match',
    score: Number((matches / outs.length).toFixed(4)),
    total: outs.length,
    matches,
    samples: perSample
  };
}
```

## Reporting and Score Display

**Location:** `/private/tmp/100-tricks-runs/d14/without/h2-eval-thresholds/r3/packages/frai-core/src/eval/reporters.js`

When generating reports (JSON or Markdown), metrics with `null` scores display as "n/a":
```javascript
lines.push(`- **Score:** ${metric.score ?? 'n/a'}`);
```

## CLI Usage

The `frai eval` command passes custom metrics through the evaluation pipeline:
```bash
frai eval --outputs outputs.json --references references.json --report report.json
```

Example from test suite showing metric in action:
```javascript
const evaluations = runEvaluations({
  outputs: ['Hello', 'friendly world'],
  references: ['hello', 'friendly world']
});
const exact = evaluations.find((metric) => metric.id === 'exact_match');
// Returns: { id: 'exact_match', score: 0.5, total: 2, matches: 1, ... }
```

## Key Design Notes

From `/private/tmp/100-tricks-runs/d14/without/h2-eval-thresholds/r3/docs/eval_harness_design.md`:
- Default metrics are lightweight and dependency-free
- The evaluation harness is extensible via `frai-core/src/eval/metrics.js`
- Custom metrics can be registered by passing evaluators to `runEvaluations`
- Future work includes integrating real toxicity/bias models and additional exporters

