import fs from 'fs';
import os from 'os';
import path from 'path';
import { afterEach, describe, expect, it } from 'vitest';

import {
  generateReport,
  loadDataset,
  runEvaluations,
  writeReport
} from './index.js';

const tmpDirs = [];
afterEach(() => {
  while (tmpDirs.length) {
    fs.rmSync(tmpDirs.pop(), { recursive: true, force: true });
  }
});

const createTempDir = () => {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-eval-'));
  tmpDirs.push(dir);
  return dir;
};

describe('Evaluation harness', () => {
  it('loads outputs and references', () => {
    const dir = createTempDir();
    const outputsPath = path.join(dir, 'outputs.json');
    const referencesPath = path.join(dir, 'references.json');
    fs.writeFileSync(outputsPath, JSON.stringify(['Hello', 'World'], null, 2));
    fs.writeFileSync(referencesPath, JSON.stringify(['hello', 'world'], null, 2));

    const dataset = loadDataset({ outputsPath, referencesPath });
    expect(dataset.outputs).toEqual(['Hello', 'World']);
    expect(dataset.references).toEqual(['hello', 'world']);
  });

  it('runs default evaluations', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'friendly world'],
      references: ['hello', 'friendly world']
    });
    const exact = evaluations.find((metric) => metric.id === 'exact_match');
    const toxicity = evaluations.find((metric) => metric.id === 'toxicity');

    expect(exact.score).toBeCloseTo(1, 4);
    expect(toxicity.score).toBe(1);
  });

  it('generates and writes report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      generatedAt: '2024-01-01T00:00:00.000Z'
    });
    expect(report.metadata.totalSamples).toBe(1);

    const dir = createTempDir();
    const jsonPath = writeReport({
      report,
      format: 'json',
      reportPath: path.join(dir, 'report.json')
    });
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    expect(fs.existsSync(jsonPath)).toBe(true);
    expect(fs.existsSync(markdownPath)).toBe(true);
  });

  it('includes passed field and empty thresholds when no thresholds provided', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toEqual([]);
  });

  it('evaluates thresholds and marks report as passed when all thresholds pass', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5, toxicity: 0.9 }
    });

    expect(report.passed).toBe(true);
    expect(report.thresholds).toHaveLength(2);
    expect(report.thresholds.every((t) => t.passed)).toBe(true);
  });

  it('evaluates thresholds and marks report as failed when any threshold fails', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.99 }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds).toHaveLength(1);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('includes threshold details in report structure', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.9 }
    });

    expect(report.thresholds[0]).toEqual({
      metric: 'exact_match',
      min: 0.9,
      score: 1,
      passed: true
    });
  });

  it('handles null metric scores as threshold failures', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: [] // empty references will cause exact_match to have null score
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.5 }
    });

    expect(report.passed).toBe(false);
    expect(report.thresholds[0].score).toBe(null);
    expect(report.thresholds[0].passed).toBe(false);
  });

  it('renders thresholds section in markdown report', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello', 'World'],
      references: ['hello', 'world']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json',
      thresholds: { exact_match: 0.99, toxicity: 0.5 }
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const markdown = fs.readFileSync(markdownPath, 'utf8');
    expect(markdown).toContain('## Thresholds');
    expect(markdown).toContain('| Metric | Minimum | Score | Status |');
    expect(markdown).toContain('| exact_match | 0.99 | 1 | FAIL |');
    expect(markdown).toContain('| toxicity | 0.5 | 1 | PASS |');
  });

  it('omits thresholds section from markdown when no thresholds', () => {
    const evaluations = runEvaluations({
      outputs: ['Hello'],
      references: ['hello']
    });
    const report = generateReport({
      evaluations,
      outputsPath: '/tmp/outputs.json',
      referencesPath: '/tmp/refs.json'
    });

    const dir = createTempDir();
    const markdownPath = writeReport({
      report,
      format: 'markdown',
      reportPath: path.join(dir, 'report.md')
    });

    const markdown = fs.readFileSync(markdownPath, 'utf8');
    expect(markdown).not.toContain('## Thresholds');
  });
});

